mapper.select:
SELECT sc.id, s.id as student_id, sc.course_id, sc.exam_id, sc.score, s.name as student_name, s.student_no, c.course_name, e.exam_name FROM student s LEFT JOIN score sc ON s.id = sc.student_id AND (#{examId} IS NULL OR sc.exam_id = #{examId}) AND (#{courseId} IS NULL OR sc.course_id = #{courseId}) AND (sc.deleted = 0 OR sc.deleted IS NULL) LEFT JOIN course c ON sc.course_id = c.id LEFT JOIN exam e ON sc.exam_id = e.id WHERE s.deleted = 0
AND s.class_id = #{classId}
AND sc.exam_id = #{examId}
ORDER BY s.student_no

SELECT COUNT(DISTINCT sc.student_id) as studentCount, AVG(sc.score) as avgScore, MAX(sc.score) as maxScore, MIN(sc.score) as minScore, SUM(CASE WHEN sc.score >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) as passRate, SUM(CASE WHEN sc.score >= 90 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) as excellentRate FROM score sc LEFT JOIN student s ON sc.student_id = s.id AND s.deleted = 0 WHERE sc.exam_id = #{examId} AND sc.deleted = 0
AND s.class_id = #{classId}
AND sc.course_id = #{courseId}

SELECT e.exam_name as examName, sc.score, e.exam_date as examDate FROM score sc LEFT JOIN exam e ON sc.exam_id = e.id AND e.deleted = 0 WHERE sc.student_id = #{studentId} AND sc.deleted = 0
AND sc.course_id = #{courseId}
ORDER BY e.exam_date
